def check_sampling_condition(f_signal: float, f_sampling: float) -> tuple:
    nyquist_rate = 2.0 * f_signal
    is_valid = f_sampling >= nyquist_rate
    if is_valid:
        alias_freq = f_signal
    else:
        alias_freq = abs(f_signal - round(f_signal / f_sampling) * f_sampling)
    return is_valid, nyquist_rate, alias_freq

import numpy as np

def reduce_bit_depth(image_uint8: np.ndarray, target_bits: int) -> np.ndarray:
    shift = 8 - target_bits
    # Turunkan bit lalu geser kembali untuk rentang dinamis penuh
    quantized = (image_uint8 >> shift) << shift
    return quantized.astype(np.uint8)
